-- 城市空气质量看板 · 数据库初始化脚本
-- 数据来源: 中国环境监测总站（全国城市空气质量实时发布平台）
-- 清洗口径: HJ 633-2012 日报（日均值统计量）  生成脚本: db/clean_build_sql.py
-- 数据量: 12 城 × 4332 行

CREATE DATABASE IF NOT EXISTS aqi_dashboard DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE aqi_dashboard;

DROP TABLE IF EXISTS air_quality;
DROP TABLE IF EXISTS city;

CREATE TABLE city (
  id         INT PRIMARY KEY AUTO_INCREMENT,
  city_name  VARCHAR(20)  NOT NULL COMMENT '城市名',
  province   VARCHAR(20)  NOT NULL COMMENT '省份',
  region     VARCHAR(20)  NOT NULL COMMENT '所属地理区',
  longitude  DECIMAL(5,2)          COMMENT '经度',
  latitude   DECIMAL(4,2)          COMMENT '纬度'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='城市表';

